import { forwardRef, useRef, useState } from 'react';
import { Pressable, TextInput, View } from 'react-native';

import { cn } from '@/lib/utils';

import { Text } from './text';

export interface OtpInputProps {
  value: string;
  onChangeText: (value: string) => void;
  /** Number of digits (default 6). */
  length?: number;
  /** Fired once the final digit is entered. */
  onComplete?: (value: string) => void;
  autoFocus?: boolean;
  error?: boolean;
  disabled?: boolean;
  /** Announced by screen readers for the (visually hidden) input. */
  accessibilityLabel?: string;
  className?: string;
  testID?: string;
}

/**
 * Segmented one-time-code input. A single hidden field drives the cells, so
 * native SMS autofill (`textContentType="oneTimeCode"` / `autoComplete="sms-otp"`)
 * works. Controlled via `value` + `onChangeText`.
 */
export const OtpInput = forwardRef<TextInput, OtpInputProps>(function OtpInput(
  {
    value,
    onChangeText,
    length = 6,
    onComplete,
    autoFocus,
    error,
    disabled,
    accessibilityLabel = 'Verification code',
    className,
    testID,
  },
  ref,
) {
  const inputRef = useRef<TextInput | null>(null);
  const [focused, setFocused] = useState(false);

  function setRefs(node: TextInput | null) {
    inputRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  }

  function handleChange(next: string) {
    const digits = next.replace(/\D/g, '').slice(0, length);
    onChangeText(digits);
    // Fire only on the transition into a full code (value holds the prior input),
    // so editing/re-autofilling an already-complete code doesn't re-trigger it.
    if (digits.length === length && value.length < length) onComplete?.(digits);
  }

  return (
    <Pressable
      // Decorative wrapper; the hidden TextInput is the real, focusable a11y target.
      accessible={false}
      disabled={disabled}
      onPress={() => inputRef.current?.focus()}
      // Pin LTR so segment 0 stays on the left even in RTL locales (codes are LTR data).
      style={{ direction: 'ltr' }}
      className={cn('flex-row gap-2', className)}
    >
      {Array.from({ length }, (_, i) => {
        const char = value[i] ?? '';
        const isActive = focused && i === value.length && value.length < length;
        return (
          <View
            key={i}
            accessibilityElementsHidden
            importantForAccessibility="no-hide-descendants"
            className={cn(
              'h-14 flex-1 items-center justify-center rounded-lg border bg-background',
              isActive ? 'border-primary' : 'border-input',
              error && 'border-destructive',
              disabled && 'opacity-50',
            )}
          >
            <Text className="text-2xl font-semibold">{char}</Text>
          </View>
        );
      })}
      <TextInput
        ref={setRefs}
        testID={testID}
        accessibilityLabel={accessibilityLabel}
        accessibilityState={{ disabled: Boolean(disabled) }}
        value={value}
        onChangeText={handleChange}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        keyboardType="number-pad"
        textContentType="oneTimeCode"
        autoComplete="sms-otp"
        autoFocus={autoFocus}
        editable={!disabled}
        maxLength={length}
        caretHidden
        // Invisible field stretched over the cells; the Pressable focuses it.
        className="absolute h-full w-full opacity-0"
      />
    </Pressable>
  );
});
